+
+using Microsoft.CodeAnalysis;
+
+public class ObjectSerializationInfoTests
+{
+    private const string FormatterInterface = "IMessagePackFormatter<MyObject>";
+
+    /// <summary>
+    /// Verifies that a formatter that the source generator declares itself is declared in full.
+    /// </summary>
+    [Theory]
+    [InlineData(ResolverRegisterInfo.FormatterPosition.UnderResolver)]
+    [InlineData(ResolverRegisterInfo.FormatterPosition.UnderDataType)]
+    public void FormatterDeclaration_SourceGeneratorDeclared(ResolverRegisterInfo.FormatterPosition position)
+    {
+        ObjectSerializationInfo info = CreateInfo(position, isFormatterRecord: false);
+
+        Assert.False(info.IsFormatterUserDeclared);
+        Assert.Equal("internal sealed class", info.FormatterDeclarationKeywords);
+        Assert.Equal($" : {FormatterInterface}", info.GetFormatterBaseList(FormatterInterface));
+    }
+
+    /// <summary>
+    /// Verifies that a formatter that the user declared is merely completed by another part of the same type,
+    /// leaving its modifiers and base list to the declaration that the user wrote.
+    /// </summary>
+    [Theory]
+    [InlineData(false, "partial class")]
+    [InlineData(true, "partial record")]
+    public void FormatterDeclaration_UserDeclared(bool isFormatterRecord, string expectedKeywords)
+    {
+        ObjectSerializationInfo info = CreateInfo(ResolverRegisterInfo.FormatterPosition.UserDeclared, isFormatterRecord);
+
+        Assert.True(info.IsFormatterUserDeclared);
+        Assert.Equal(expectedKeywords, info.FormatterDeclarationKeywords);
+        Assert.Equal(string.Empty, info.GetFormatterBaseList(FormatterInterface));
+    }
+
+    private static ObjectSerializationInfo CreateInfo(ResolverRegisterInfo.FormatterPosition position, bool isFormatterRecord) => new()
+    {
+        DataType = new QualifiedNamedTypeName(TypeKind.Class)
+        {
+            Container = new NamespaceTypeContainer("My"),
+            Name = "MyObject",
+        },
+        Formatter = new QualifiedNamedTypeName(TypeKind.Class, isFormatterRecord)
+        {
+            Container = new NamespaceTypeContainer("My"),
+            Name = "MyObjectFormatter",
+        },
+        FormatterLocation = position,
+        IsClass = true,
+        GenericTypeParameters = Array.Empty<GenericTypeParameterInfo>(),
+        ConstructorParameters = Array.Empty<MemberSerializationInfo>(),
+        InitMembers = Array.Empty<MemberSerializationInfo>(),
+        IsIntKey = false,
+        Members = Array.Empty<MemberSerializationInfo>(),
+        HasIMessagePackSerializationCallbackReceiver = false,
+        NeedsCastOnAfter = false,
+        NeedsCastOnBefore = false,
+    };
+}

